package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.*;import cl.nexbyte.siger.institucional.robustez.*;
import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.SpringBootConfiguration;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.test.annotation.DirtiesContext;import org.springframework.test.web.servlet.MockMvc;import org.springframework.mock.web.MockHttpSession;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(classes=ContinuidadHttpTest.Application.class,properties={"institucional.nucleo.habilitado=true","institucional.identidad.habilitada=true"}) @AutoConfigureMockMvc @DirtiesContext
class ContinuidadHttpTest {
 @SpringBootConfiguration @EnableAutoConfiguration @Import({SeguridadInstitucional.class,NucleoController.class,NucleoU2Controller.class,ContinuidadU2Controller.class,ErroresTecnicos.class,JsonEstricto.class,AreasHttpTest.Fixture.class})static class Application{}
 @Autowired MockMvc http;@Autowired AreasFixture f;
 MockHttpSession login(String name)throws Exception{var s=new MockHttpSession();http.perform(post("/nucleo/login").secure(true).session(s).with(csrf()).param("username",name).param("password",f.passwords.get(name))).andExpect(status().isNoContent());return s;}
 String send(MockHttpSession s,String path,Object body,int status)throws Exception{var result=http.perform(post(path).secure(true).session(s).with(csrf()).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(f.d.mapper.writeValueAsString(body))).andExpect(status().is(status)).andReturn();return result.getResponse().getContentAsString();}
 UUID result(String json){return UUID.fromString(f.d.mapper.readTree(json).path("id").asString());}
 UUID req(MockHttpSession dist,MockHttpSession h)throws Exception{var com=f.d.nuevaWeb();var sol=result(send(dist,"/nucleo/institucional/comunicaciones/"+com+"/distribuir",new NucleoU2.Encaminar(0,new ContratosNucleo.NuevoDestino("UPR","DEMO_SEDE_A",f.headA,"AREA_A"),"Clasificación sintética",null),200));return result(send(h,"/nucleo/institucional/solicitudes/"+sol+"/asumir",new NucleoU2.Asumir(0,f.profA,"Asunción profesional",null),200));}
 UUID caso(MockHttpSession h,UUID q)throws Exception{return result(send(h,"/nucleo/institucional/requerimientos/"+q+"/casos",new NucleoU2.Apertura(0,f.profA,"Objetivo independiente"),200));}
 @Test void derivacionYTransferenciaConSesionesRealesCsrfYSegregacion()throws Exception{
  var dist=login("distribuidor");var h=login("jefe.a");var target=login("jefe.b");var pro=login("prof.a");var ti=login("ti.areas");var q=req(dist,h);var cas=caso(h,q);String base="/nucleo/institucional/continuidad";
  var request=new ContinuidadU2.Derivar(0,new ContratosNucleo.NuevoDestino("UPR","DEMO_SEDE_A",f.headB,"AREA_B"),"Motivo documentado","Paquete limitado","Objetivo del sucesor");String path=base+"/casos/"+cas+"/derivar";
  http.perform(post(path).secure(true).session(h).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(f.d.mapper.writeValueAsString(request))).andExpect(status().isForbidden());send(pro,path,request,404);var p=result(send(h,path,request,200));
  http.perform(get(base).secure(true).session(target)).andExpect(status().isOk()).andExpect(jsonPath("$.derivaciones[0].summary_text").value("Paquete limitado"));http.perform(get(base+"/casos/"+cas).secure(true).session(target)).andExpect(status().isNotFound());http.perform(get(base).secure(true).session(ti)).andExpect(jsonPath("$.derivaciones.length()").value(0));
  send(target,base+"/derivaciones/"+p+"/decidir",new ContinuidadU2.Resolver(0,"ACEPTADA",f.profB,"Aceptación fundada"),200);http.perform(get("/nucleo/casos/"+cas).secure(true).session(pro)).andExpect(jsonPath("$.estado").value("EN_GESTION"));assertEquals(2,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_case WHERE requirement_id=?",Long.class,q.toString()));
  var assignment=f.d.db.sql.queryForObject("SELECT assignment_id FROM institution_assignment_current WHERE case_id=?",String.class,cas.toString());send(pro,base+"/casos/"+cas+"/acuse",new ContinuidadU2.Acusar(UUID.fromString(assignment)),200);assertEquals(1,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_assignment_receipt WHERE assignment_id=?",Long.class,assignment));
  var t=result(send(h,base+"/requerimientos/"+q+"/transferir",new ContinuidadU2.Trasladar(2,new ContratosNucleo.NuevoDestino("UPR","DEMO_SEDE_A",f.headB,"AREA_B"),"Principal distinto","Resumen de coordinación"),200));send(target,base+"/transferencias/"+t+"/decidir",new ContinuidadU2.Resolver(0,"ACEPTADA",null,"Asume principal"),200);http.perform(get("/nucleo/institucional/requerimientos/"+q).secure(true).session(h)).andExpect(status().isNotFound());http.perform(get("/nucleo/casos/"+cas).secure(true).session(target)).andExpect(status().isNotFound());http.perform(get("/nucleo/casos/"+cas).secure(true).session(pro)).andExpect(status().isOk());
 }
 @Test void reaperturaHttpCoordinaAutoridadPrincipalYSinAtajoHistorico()throws Exception{
  var dist=login("distribuidor");var h=login("jefe.a");var pro=login("prof.a");var q=req(dist,h);var cas=caso(h,q);send(pro,"/nucleo/casos/"+cas+"/solicitar-termino",new ContratosNucleo.Decision(0,"Término fundado"),200);send(h,"/nucleo/casos/"+cas+"/cerrar",new ContratosNucleo.Decision(1,"Revisión confirma"),200);send(h,"/nucleo/institucional/requerimientos/"+q+"/cerrar",new ContratosNucleo.Decision(1,"Cierre global"),200);
  String base="/nucleo/institucional/continuidad";var p=result(send(pro,base+"/casos/"+cas+"/reaperturas",new ContinuidadU2.Reabrir(2,"Error revisable","Antecedente documentado existente"),200));send(h,"/nucleo/reaperturas/"+p+"/aprobar",Map.of("revision",0,"revisionCaso",2,"fundamento","No usar semántica histórica"),409);send(h,base+"/reaperturas/"+p+"/decidir",new ContinuidadU2.DecidirReapertura(0,2,"APROBADA","Sin aprobación principal aún"),409);send(h,base+"/reaperturas/"+p+"/reactivacion-req",new ContinuidadU2.Reactivar(0,2,"Decisión humana expresa"),200);http.perform(get("/nucleo/institucional/requerimientos/"+q).secure(true).session(h)).andExpect(jsonPath("$.state").value("TERMINADO"));send(h,base+"/reaperturas/"+p+"/decidir",new ContinuidadU2.DecidirReapertura(1,2,"APROBADA","Revisión del Caso confirma"),200);http.perform(get("/nucleo/casos/"+cas).secure(true).session(pro)).andExpect(jsonPath("$.estado").value("EN_GESTION"));http.perform(get("/nucleo/casos/"+cas+"/periodos").secure(true).session(pro)).andExpect(jsonPath("$.length()").value(1));
 }
}
